//! The shipped card ruleset: every band's table in one module.
//!
//! Generated by `tools/rules-aggregate.mjs` -- do not edit. The band crates
//! stay one-per-band (and one .rs per card) for authors; unifying the
//! *artifact* keeps the SDK and allocator linked once instead of once per
//! band, which is most of the size of a module.

#![cfg_attr(target_arch = "wasm32", no_std)]

/// Roster metadata sources (ABI v63): card ordinals + the skill crates'
/// character / band tables. `bandori_metadata` builds the blob on request.
static ROSTER: card_sdk::meta::RosterSources = card_sdk::meta::RosterSources {
    card_ordinals: ruleset_core::roster_order::CARDS,
    lists: &[
        card_sdk::meta::RosterList {
            kind: "character",
            ordinals: ruleset_core::roster_order::CHARACTERS,
            rows: skill_characters::roster_table::meta_rows,
        },
        card_sdk::meta::RosterList {
            kind: "band",
            ordinals: ruleset_core::roster_order::BANDS,
            rows: skill_bands::roster_table::meta_rows,
        },
    ],
};

card_sdk::bandori_ruleset!(
    card_ag::CARDS,
    card_crychic::CARDS,
    card_general::CARDS,
    card_hhw::CARDS,
    card_morfonica::CARDS,
    card_mujica::CARDS,
    card_mygo::CARDS,
    card_pp::CARDS,
    card_ppp::CARDS,
    card_ras::CARDS,
    card_roselia::CARDS,
    card_sumimi::CARDS,
    skill_bands::CARDS,
    skill_characters::CARDS,
    rules_tiles::CARDS,
    rules_tile_marks::CARDS,
    rules_status::CARDS,
    rules_events::CARDS
; roster: &ROSTER
);
